INSERT INTO `movies` VALUES (1,'Cảm Ơn Người Đã Thức Cùng Tôi','Giữa thành phố không ngủ, có ai vì ta mà dừng lại?','cam-on-nguoi-da-thuc-cung-toi','Khắc họa cuộc sống về đêm của người trẻ nơi đô thị, những chuyến bay xa xứ và hành trình theo đuổi đam mê điện ảnh đầy cô độc nhưng được sưởi ấm bởi những tâm hồn đồng điệu.',108,'2026-02-27','Chung Chí Công','Nguyễn Hùng, Trâm Anh, Khắc Minh','[{\"name\":\"Nguyễn Hùng\",\"role\":\"Minh\",\"avatar_url\":\"https://th.bing.com/th/id/OIP.JGRqRITC5H3GnAixlnQAPAHaKI?w=132&h=180&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"},{\"name\":\"Trâm Anh\",\"role\":\"Nhã\",\"avatar_url\":\"data:image/webp;base64,\"},{\"name\":\"Khắc Minh\",\"role\":\"Thành\",\"avatar_url\":\"data:image/webp;base64,\"}]','Tiếng Việt','Việt Nam','T13','/uploads/posters/1792983106605-ff1543b6af09.webp','/uploads/posters/1792983106611-31a80569ebe0.webp','[\"data:image/webp;base64,\",\"https://th.bing.com/th/id/OIP.E0tf0UNERzz1y6259c36TgHaD3?w=345&h=180&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"]',NULL,'https://www.youtube.com/watch?v=z45Beypyejw&pp=ygUxdHJhaWxlckPhuqNtIMagbiBOZ8aw4budaSDEkMOjIFRo4bupYyBDw7luZyBUw7RpIA%3D%3D','now_showing',4.50,2,'2026-10-16 04:13:22','2026-10-26 04:05:35'),(2,'Nhà Ba Tôi Một Phòng','Căn phòng nhỏ nhưng chở che cả một đời con.','nha-ba-toi-mot-phong','Cuộc sống giản dị, đầy ắp tiếng cười nhưng cũng không ít trăn trở của một người cha đơn thân cùng con trai trong căn phòng thuê chật hẹp giữa lòng phố thị náo nhiệt.',110,'2026-02-17','Trường Giang','Trường Giang, Minh Anh, HIEUTHUHAI, ...','[{\"name\":\"Trường Giang\",\"role\":\"Ông Thạch\",\"avatar_url\":\"data:image/webp;base64,\"},{\"name\":\"Đoàn Minh Anh\",\"role\":\"Hoài An\",\"avatar_url\":\"https://th.bing.com/th/id/OIP.XTdSK-QYB8E20sYbxj53MAHaE8?w=298&h=199&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"},{\"name\":\"Anh Tú Atus\",\"role\":\"Phát\",\"avatar_url\":\"https://th.bing.com/th/id/OIP.SWvVGjappXIKOfdHrZg12QHaLF?w=186&h=278&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"},{\"name\":\"Lê Khánh\",\"role\":\"Cô Châu\",\"avatar_url\":\"https://th.bing.com/th/id/OIP.GmhzGfoOcErkFEYrMqGeiwHaLH?w=133&h=200&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"}]','Tiếng Việt','Việt Nam','P','/uploads/posters/1792983489202-2674ef003c35.webp','/uploads/posters/1792983489210-0c7a4b4cc2dd.webp','[\"data:image/webp;base64,\",\"https://th.bing.com/th/id/OIP.ChkcKKgr0OQO7t4v4ksxpQHaE8?w=253&h=180&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"]',NULL,NULL,'coming_soon',0.00,0,'2026-10-16 04:13:22','2026-10-26 11:06:41'),(3,'Thỏ Ơi!','Hạnh phúc không nằm ở đích đến, mà ở người cùng ta sẻ chia.','tho-oi','Câu chuyện xoay quanh mối quan hệ gia đình nhiều khúc mắc giữa các thế hệ trẻ và phụ huynh, nơi những hiểu lầm, áp lực cuộc sống hiện đại dần được hóa giải bằng tình yêu thương và sự thấu hiểu.',115,'2026-02-17','Trấn Thành','Trấn Thành, LyLy, Pháo, Đinh Ngọc Diệp, BB Trần','[{\"name\":\"Trấn Thành \",\"role\":\"Trần Trung Kim\",\"avatar_url\":\"https://th.bing.com/th/id/OIP.Ud7P64IdtaXYcsOIfCy7ygHaE2?w=256&h=180&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"},{\"name\":\"Pháo\",\"role\":\"Nhật Hạ\",\"avatar_url\":\"https://th.bing.com/th/id/OIP.Z-GsW2WwszYdEw-FaFBXWQHaLG?w=186&h=279&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"},{\"name\":\"LyLy\",\"role\":\"Chị Bờ Vai \",\"avatar_url\":\"https://th.bing.com/th/id/OIP.3watMe0GOT8DZuWwW0v7eQHaLG?w=132&h=180&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"},{\"name\":\"Văn Mai Hương\",\"role\":\"Hải Lan \",\"avatar_url\":\"https://th.bing.com/th/id/OIP.zrHB7bjYS7yeQYbUnPWwHAHaLH?w=132&h=180&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"},{\"name\":\"Vĩnh Đam\",\"role\":\"Thế Phong\",\"avatar_url\":\"data:image/webp;base64,\"},{\"name\":\"Quốc Anh\",\"role\":\"Ngọc Sơn\",\"avatar_url\":\"data:image/webp;base64,\"}]','Tiếng Việt','Việt Nam','T16','/uploads/posters/1792982147515-b639fe426d5c.webp','/uploads/posters/1792982147519-0f6870f65670.webp','[\"data:image/webp;base64,\",\"https://th.bing.com/th/id/OIP.lQAXh5XOJObye_lZriZECwHaE8?w=227&h=180&c=7&r=0&o=7&dpr=1.3&pid=1.7&rm=3\"]',NULL,'https://www.youtube.co