INSERT INTO `reviews` VALUES (1,2,1,5,'Phim rất rợn, âm thanh xuất sắc!','2026-10-16 04:13:23'),(2,3,1,4,'Cốt truyện hay, đoạn cuối hơi vội.','2026-10-16 04:13:23'),(3,2,3,5,'Phim nhẹ nhàng, xem xong thấy nhớ thời học sinh.','2026-10-16 04:13:23'),(10,10,12,5,'Gây cấn, vừa hài vừa buồn vừa sợ mà thấy hài nhiều hơn. Phim đáng xem, siu hay, rất thích xem phim Việt.','2026-10-25 13:24:29'),(11,11,12,5,'Phim rất hay luôn nha, mình thấy nhiều bạn bảo không bằng Thiên Đường Máu nhưng riêng mình thấy phim có chất riêng. Khúc đầu hơi hụt hẫng xíu nhưng càng xem càng có nhiều tình tiết ăn sâu vào não, kiểu tình tiết gài gắm cũng rất ẩn ý. Tóm lại bản thân mình thấy rất đáng tiền!','2026-10-25 10:24:29'),(12,8,8,5,'Phim hay, Gay cấn, kịch tính, hù dọa người xem','2026-10-26 04:29:30');
/*!40000 ALTER TABLE `reviews` ENABLE KEYS */;
UNLOCK TABLES;

